import sys
MOD=998244353

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n=data[0]; a=data[1:]
    mx=max(a)
    spf=list(range(mx+1))
    for p in range(2,int(mx**0.5)+1):
        if spf[p]==p:
            for v in range(p*p,mx+1,p):
                if spf[v]==v: spf[v]=p
    phi=list(range(mx+1))
    for p in range(2,mx+1):
        if phi[p]==p:
            for v in range(p,mx+1,p): phi[v]-=phi[v]//p
    sums=[0]*(mx+1)
    ans=0; weight=1
    out=[]
    for x in a:
        ds=[1]; y=x
        while y>1:
            p=spf[y]; power=p; e=0
            while y%p==0:
                y//=p; e+=1
            old=ds[:]
            for _ in range(e):
                ds.extend(d*power for d in old)
                power*=p
        add=0
        for d in ds:
            add += phi[d]*sums[d]
        ans=(2*ans+add)%MOD
        out.append(str(ans))
        for d in ds: sums[d]=(sums[d]+weight)%MOD
        weight=weight*2%MOD
    print('\n'.join(out))
if __name__=='__main__': main()

