import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:1+n]
    limit = max(a, default=1)
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p
    omega = [0] * (limit + 1)
    for x in range(2, limit + 1):
        omega[x] = omega[x // spf[x]] + 1
    nim = 0
    for x in a:
        nim ^= omega[x]
    print('Anna' if nim else 'Bruno')

if __name__ == '__main__':
    main()

