import sys

def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    edges = [None] * M
    for i in range(M):
        a, b, c = map(int, input().split())
        edges[i] = (a - 1, b - 1, c)
    queries = []
    closed = [False] * M
    for _ in range(Q):
        z = list(map(int, input().split()))
        if z[0] == 1:
            i = z[1] - 1
            closed[i] = True
            queries.append((1, i))
        else:
            queries.append((2, z[1] - 1, z[2] - 1))

    inf = 10**30
    d = [[inf] * N for _ in range(N)]
    for i in range(N):
        d[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not closed[i]:
            d[a][b] = d[b][a] = c
    for k in range(N):
        dk = d[k]
        for i in range(N):
            dik = d[i][k]
            if dik == inf:
                continue
            di = d[i]
            for j in range(N):
                v = dik + dk[j]
                if v < di[j]:
                    di[j] = v

    ans = []
    for q in reversed(queries):
        if q[0] == 2:
            val = d[q[1]][q[2]]
            ans.append(str(val if val < inf else -1))
        else:
            a, b, c = edges[q[1]]
            col_a = [d[i][a] for i in range(N)]
            col_b = [d[i][b] for i in range(N)]
            row_a = d[a][:]
            row_b = d[b][:]
            for i in range(N):
                x = col_a[i] + c
                y = col_b[i] + c
                di = d[i]
                ra = row_a
                rb = row_b
                for j in range(N):
                    v1 = x + rb[j]
                    v2 = y + ra[j]
                    if v1 < di[j]:
                        di[j] = v1
                    if v2 < di[j]:
                        di[j] = v2
    print('\n'.join(reversed(ans)))

if __name__ == '__main__':
    main()

