class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)
        mod = 10**9 + 7
        C = [[0] * (n + 1) for _ in range(n + 1)]
        C[0][0] = 1
        for i in range(1, n + 1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod
        good = [False] * (n + 1)
        for t in range(1, n + 1):
            x = t
            steps = 0
            while x > 1:
                x = x.bit_count()
                steps += 1
            good[t] = steps <= k - 1
        ans = 0
        for t in range(1, n + 1):
            if not good[t]:
                continue
            ones = 0
            ways = 0
            for i, ch in enumerate(s):
                if ch == '1':
                    rem = n - i - 1
                    need = t - ones
                    if 0 <= need <= rem:
                        ways += C[rem][need]
                    ones += 1
                    if ones > t:
                        break
            ans = (ans + ways) % mod
        return ans

