import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    N, M, Q = next(it), next(it), next(it)
    people = [(next(it), next(it)) for _ in range(M)]
    queries = [(next(it), next(it)) for _ in range(Q)]
    out = []
    for L, R in queries:
        parent = list(range(N + 1))
        size = [1] * (N + 1)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        for i in range(L - 1, R):
            s, t = people[i]
            a, b = find(s), find(t)
            if a != b:
                if size[a] < size[b]:
                    a, b = b, a
                parent[b] = a
                size[a] += size[b]

        # Compress all town identifiers after processing the equalities.
        roots = [0] * (N + 1)
        for x in range(1, N + 1):
            roots[x] = find(x)
        adj = [[] for _ in range(N + 1)]
        indeg = [0] * (N + 1)
        ok = True
        for i in range(L - 1, R):
            s, t = people[i]
            a, b = min(s, t), max(s, t)
            endpoint = roots[s]
            for x in range(a + 1, b):
                inside = roots[x]
                if inside == endpoint:
                    ok = False
                    break
                if s < t:
                    u, v = endpoint, inside
                else:
                    u, v = inside, endpoint
                adj[u].append(v)
                indeg[v] += 1
            if not ok:
                break
        if not ok:
            out.append('No')
            continue
        stack = [x for x in range(1, N + 1) if roots[x] == x and indeg[x] == 0]
        seen = 0
        while stack:
            u = stack.pop()
            seen += 1
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    stack.append(v)
        out.append('Yes' if seen == sum(1 for x in range(1, N + 1) if roots[x] == x) else 'No')
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    solve()

