import sys, heapq

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    H,W,X=data[:3]; P,Q=data[3]-1,data[4]-1
    vals=data[5:]
    grid=[vals[i*W:(i+1)*W] for i in range(H)]
    seen=bytearray(H*W)
    start=P*W+Q
    seen[start]=1
    strength=grid[P][Q]
    heap=[]
    def add(r,c):
        idx=r*W+c
        if not seen[idx]:
            seen[idx]=1
            heapq.heappush(heap,(grid[r][c],idx))
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        nr,nc=P+dr,Q+dc
        if 0<=nr<H and 0<=nc<W: add(nr,nc)
    while heap:
        value,idx=heap[0]
        if value*X>=strength: break
        heapq.heappop(heap)
        strength+=value
        r,c=divmod(idx,W)
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W: add(nr,nc)
    print(strength)

if __name__=='__main__': main()

