import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:1+n]
    # The mountain-fold pattern is periodic modulo 2^L, where L exceeds
    # every offset by at least two bits.
    L = max(2, max(a).bit_length() + 2)
    period = 1 << L
    limit = (1 << 100) - a[-1] - 1
    end = min(period, limit + 1)
    best = 0
    for x in range(1, end + 1):
        score = 0
        for off in a:
            y = x + off
            low = y & -y
            if ((y // low) & 3) == 1:
                score += 1
        if score > best:
            best = score
    print(best)

if __name__ == '__main__':
    main()

