    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    rank = 0
    pivots = []
    for col in range(n):
        q = next((i for i in range(rank, n) if (rows[i] >> col) & 1), None)
        if q is None:
            continue
        rows[rank], rows[q] = rows[q], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free_cols = [c for c in range(n) if c not in pivot_set]
    shift = 2 if m > 0 and len(free_cols) <= 58 else 0
    values = [0] * n
    for j, f in enumerate(free_cols):
        vec = 1 << f
        for i, col in enumerate(pivots):
            if (rows[i] >> f) & 1:
                vec |= 1 << col
        for v in range(n):
