from functools import lru_cache
from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Clockwise order in screen coordinates: SE, SW, NW, NE.
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))

        @lru_cache(None)
        def run(r: int, c: int, d: int, phase: int, can_turn: bool) -> int:
            expected = 2 if phase == 0 else 0
            if not (0 <= r < n and 0 <= c < m) or grid[r][c] != expected:
                return 0
            nr, nc = r + dirs[d][0], c + dirs[d][1]
            value = 1 + run(nr, nc, d, 1 - phase, can_turn)
            if can_turn:
                td = (d + 1) % 4
                nr, nc = r + dirs[td][0], c + dirs[td][1]
                value = max(value, 1 + run(nr, nc, td, 1 - phase, False))
            return value

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d, (dr, dc) in enumerate(dirs):
                    answer = max(answer, 1 + run(r + dr, c + dc, d, 0, True))
        return answer

