class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        coeff = []
        p10 = [pow(10, i, k) for i in range(n)]
        for j in range(m):
            if n - 1 - j == j:
                c = p10[j]
            else:
                c = (p10[j] + p10[n - 1 - j]) % k
            coeff.append(c)

        full = (1 << k) - 1
        suffix = [0] * (m + 1)
        suffix[m] = 1
        for i in range(m - 1, -1, -1):
            mask = suffix[i + 1]
            c = coeff[i]
            reachable = 0
            for d in range(10):
                shift = (d * c) % k
                if shift == 0:
                    rotated = mask
                else:
                    rotated = ((mask << shift) | (mask >> (k - shift))) & full
                reachable |= rotated
            suffix[i] = reachable

        digits = []
        rem = 0
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                need = (-rem - d * c) % k
                if (suffix[i + 1] >> need) & 1:
                    digits.append(str(d))
                    rem = (rem + d * c) % k
                    break
        left = ''.join(digits)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

