from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        levels = n.bit_length()
        jump = [nxt]
        aggregate = [[nums[i] * (nxt[i] - i) for i in range(n)]]
        for _ in range(1, levels):
            prev_jump = jump[-1]
            prev_aggregate = aggregate[-1]
            jump.append([prev_jump[prev_jump[i]] if prev_jump[i] < n else n
                         for i in range(n)])
            aggregate.append([prev_aggregate[i] +
                              (prev_aggregate[prev_jump[i]] if prev_jump[i] < n else 0)
                              for i in range(n)])

        prefix = [0] * (n + 1)
        for i, value in enumerate(nums):
            prefix[i + 1] = prefix[i] + value

        def increments(left: int, right: int) -> int:
            pos = left
            raised_sum = 0
            for level in range(levels - 1, -1, -1):
                destination = jump[level][pos]
                if destination <= right:
                    raised_sum += aggregate[level][pos]
                    pos = destination
            raised_sum += nums[pos] * (right - pos + 1)
            return raised_sum - (prefix[right + 1] - prefix[left])

        answer = 0
        for left in range(n):
            low, high = left - 1, n
            while high - low > 1:
                middle = (low + high) // 2
                if increments(left, middle) <= k:
                    low = middle
                else:
                    high = middle
            answer += low - left + 1
        return answer

