import sys
from collections import defaultdict

MOD = 998244353

def row_trans(row, top):
    w = len(row)
    result = defaultdict(int)
    for first_left in (0, 1):
        # map (current horizontal edge bit, bottom-mask-so-far) -> count
        dp = {(first_left, 0): 1}
        for j, ch in enumerate(row):
            up = (top >> j) & 1
            ndp = defaultdict(int)
            for (left, mask), ways in dp.items():
                for right in (0, 1):
                    for down in (0, 1):
                        if ch == 'A':
                            valid = left + right == 1 and up + down == 1
                        else:
                            valid = (left == right and up == down and left + up == 1)
                        if valid:
                            ndp[(right, mask | (down << j))] += ways
            dp = ndp
        for (last_right, mask), ways in dp.items():
            if last_right == first_left:
                result[mask] += ways
    return result

def solve_case(grid):
    h, w = len(grid), len(grid[0])
    # Use the shorter dimension as the transfer width.
    if h < w:
        grid = [''.join(grid[i][j] for i in range(h)) for j in range(w)]
        h, w = w, h
    nstates = 1 << w
    trans_cache = []
    for row in grid:
        cache = [None] * nstates
        for mask in range(nstates):
            cache[mask] = row_trans(row, mask)
        trans_cache.append(cache)
    ans = 0
    for start in range(nstates):
        dp = {start: 1}
        for r in range(h):
            ndp = defaultdict(int)
            cache = trans_cache[r]
            for top, ways in dp.items():
                for bottom, cnt in cache[top].items():
                    ndp[bottom] = (ndp[bottom] + ways * cnt) % MOD
            dp = ndp
        ans = (ans + dp.get(start, 0)) % MOD
    return ans

def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0]); p = 1
    out = []
    for _ in range(t):
        h = int(data[p]); w = int(data[p+1]); p += 2
        grid = [data[p+i].decode() for i in range(h)]
        p += h
        out.append(str(solve_case(grid)))
    print('\n'.join(out))

if __name__ == '__main__':
    main()

