        postorder = []
        stack = [(0, False)]
        while stack:
            v, done = stack.pop()
            if done:
                postorder.append(v)
            else:
                stack.append((v, True))
                for c in reversed(children[v]):
                    stack.append((c, False))

        pos = [0] * n
        size = [1] * n
        for i, v in enumerate(postorder):
            pos[v] = i
            for c in children[v]:
                size[v] += size[c]

        t = ''.join(s[v] for v in postorder)
        odd = [0] * n
        l = 0
        r = -1
        for i in range(n):
            k = 1 if i > r else min(odd[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < n and t[i - k] == t[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        even = [0] * n
        l = 0
        r = -1
        for i in range(n):
            k = 0 if i > r else min(even[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < n and t[i - k - 1] == t[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        ans = [False] * n
        for v in range(n):
            end = pos[v] + 1
            start = end - size[v]
            length = size[v]
            if length & 1:
                center = (start + end - 1) // 2
                ans[v] = odd[center] >= length // 2 + 1
            else:
                center = (start + end) // 2
                ans[v] = even[center] >= length // 2
