import itertools

MOD = 998244353

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    s = data[1].decode()
    whites = [i for i, c in enumerate(s) if c == 'W']
    blacks = [i for i, c in enumerate(s) if c == 'B']

    answer = 0
    for assignment in itertools.permutations(blacks):
        intervals = sorted(
            (assignment[k], whites[k])
            for k in range(n)
            if assignment[k] < whites[k]
        )
        if not intervals or intervals[0][0] != 0:
            continue
        reach = intervals[0][1]
        for left, right in intervals[1:]:
            if left > reach:
                break
            reach = max(reach, right)
        else:
            if reach == 2 * n - 1:
                answer += 1

    print(answer % MOD)

if __name__ == '__main__':
    main()

