 N=2*n
 g=[[] for _ in range(N)]
 def add(u,v,c,w):
  g[u].append([v,len(g[v]),c,w]); g[v].append([u,len(g[u])-1,0,-w])
 def inn(v): return 2*v
 def out(v): return 2*v if v==s or v==t else 2*v+1
 for v in range(n):
