class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        for _ in range(t):
            z = cnt[25]
            nxt = [0] * 26
            nxt[0] = z
            nxt[1] = (cnt[0] + z) % mod
            for i in range(2, 26):
                nxt[i] = cnt[i - 1]
            cnt = nxt
