class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def variants(x):
            s = list(str(x))
            vals = {x}
            for i in range(len(s)):
                for j in range(i + 1, len(s)):
                    t = s[:]
                    t[i], t[j] = t[j], t[i]
                    vals.add(int(''.join(t)))
            return vals

        forms = [variants(x) for x in nums]
        ans = 0
        for i in range(len(nums)):
            for j in range(i):
                if nums[j] in forms[i] or nums[i] in forms[j]:
