from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        cnt = Counter(nums)
        total = sum(nums)

        # Treat each distinct value as the outlier, largest first.
        for x in sorted(cnt, reverse=True):
            remaining = total - x
            if remaining % 2 != 0:
                continue

            special_sum = remaining // 2
            needed = 2 if special_sum == x else 1
            if cnt.get(special_sum, 0) >= needed:
                return x

