class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq
        def prime(x):
            if x < 2:
                return False
            if x % 2 == 0:
                return x == 2
            d = 3
            while d * d <= x:
                if x % d == 0:
                    return False
                d += 2
            return True

        if prime(n) or prime(m):
            return -1
        digits = len(str(n))
        places = [10 ** i for i in range(digits)]
        inf = 10**30
        dist = {n: n}
        heap = [(n, n)]
        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            for place in places:
                digit = (x // place) % 10
                for delta in (-1, 1):
                    nd = digit + delta
                    if not (0 <= nd <= 9):
                        continue
                    y = x + delta * place
                    if prime(y):
                        continue
                    nc = cost + y
                    if nc < dist.get(y, inf):
                        dist[y] = nc
                        heapq.heappush(heap, (nc, y))
        return -1

