from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z0[i] is the common-prefix length of nums and nums[i:].
        z0 = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z0[i] = min(right - i + 1, z0[i - left])
            while i + z0[i] < n and nums[z0[i]] == nums[i + z0[i]]:
                z0[i] += 1
            if i + z0[i] - 1 > right:
                left, right = i, i + z0[i] - 1

        ans = 0
        for i in range(1, n - 1):
            # First condition: nums1 is a prefix of nums2. A sufficiently
            # long nums2 can end at any j from 2*i through n-1.
            first_count = max(0, n - 2 * i) if z0[i] >= i else 0
            ans += first_count

            # For nums2 prefix of nums3, compute Z-values on nums[i:].
            m = n - i
            z = [0] * m
            left = right = 0
            for k in range(1, m):
                if k <= right:
                    z[k] = min(right - k + 1, z[k - left])
                while k + z[k] < m and nums[i + z[k]] == nums[i + k + z[k]]:
                    z[k] += 1
                if k + z[k] - 1 > right:
                    left, right = k, k + z[k] - 1
                if z[k] >= k and not (z0[i] >= i and k >= i):
                    ans += 1
        return ans

