class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reverse edges let us traverse from 0 to every node that can reach it.
        rev = [[] for _ in range(n)]
        weights = set()
        for a, b, w in edges:
            rev[b].append((a, w))
            weights.add(w)
        vals = sorted(weights)

        def feasible(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in rev[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        count += 1
                        stack.append(u)
            return count == n

        lo, hi = 0, len(vals) - 1
        if not feasible(vals[hi]):
            return -1
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(vals[mid]):
                hi = mid
            else:
                lo = mid + 1
        return vals[lo]

