class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j
        base = s.count('1')
        gain = 0
        for k in range(1, len(runs) - 1):
            if runs[k][0] == '1':
                gain = max(gain, runs[k - 1][1] + runs[k + 1][1])
        return base + gain

